import time
import pytest
from functional import memoize, compose, pipe, retry


def test_memoize_basic():
    calls = []

    @memoize
    def add(a, b):
        calls.append((a, b))
        return a + b

    assert add(1, 2) == 3
    assert add(1, 2) == 3  # cached
    assert len(calls) == 1


def test_memoize_different_args():
    @memoize
    def square(n):
        return n * n

    assert square(3) == 9
    assert square(4) == 16
    assert square(3) == 9


def test_compose_two_fns():
    double = lambda x: x * 2
    inc = lambda x: x + 1
    double_then_inc = compose(inc, double)
    assert double_then_inc(3) == 7  # inc(double(3)) = inc(6) = 7


def test_compose_order():
    # compose(f, g)(x) == f(g(x)) — rightmost applied first
    f = lambda x: x + "!"
    g = lambda x: x.upper()
    assert compose(f, g)("hello") == "HELLO!"


def test_compose_single():
    double = lambda x: x * 2
    assert compose(double)(5) == 10


def test_pipe_basic():
    result = pipe(3, lambda x: x * 2, lambda x: x + 1)
    assert result == 7  # 3 -> 6 -> 7


def test_pipe_single_fn():
    assert pipe("hello", str.upper) == "HELLO"


def test_retry_succeeds_first_try():
    calls = []

    def always_ok():
        calls.append(1)
        return 42

    assert retry(always_ok, times=3) == 42
    assert len(calls) == 1


def test_retry_succeeds_after_failures():
    calls = []

    def flaky():
        calls.append(1)
        if len(calls) < 3:
            raise ValueError("not yet")
        return "ok"

    assert retry(flaky, times=5) == "ok"
    assert len(calls) == 3


def test_retry_exhausted():
    def always_fail():
        raise RuntimeError("boom")

    with pytest.raises(RuntimeError):
        retry(always_fail, times=3)
